INSERT INTO public.address_th_subdistrict (id, zip_code, subdistrict_name_th, subdistrict_name_en, district_id, district_name_th, district_name_en)
SELECT v.id, v.zip_code, v.name_th, v.name_en, d.id::bigint, d.district_name_th, d.district_name_en
FROM (VALUES
  ('410116', 41000, 'ต.นาข่า', 'Na Kha', '4101'),
  ('500108', 50200, 'ต.สุเทพ', 'Suthep', '5001'),
  ('830104', 83000, 'ต.รัษฎา', 'Ratsada', '8301')
) AS v(id, zip_code, name_th, name_en, district_code)
JOIN public.address_th_district AS d ON d.id = v.district_code;

-- Step 2: re-point saved addresses to the code that officially holds the name the member picked
UPDATE public.user_address AS ua
SET subdistrict_code = m.new_code,
    subdistrict = CASE WHEN ua.subdistrict = m.old_code THEN m.new_code ELSE ua.subdistrict END
FROM (VALUES
  ('110402', '110401'),
  ('141108', '141109'),
  ('141109', '141108'),
  ('410111', '410116'),
  ('461803', '461804'),
  ('461804', '461805'),
  ('461805', '461803'),
  ('481202', '481203'),
  ('481203', '481202'),
  ('500109', '500108')
) AS m(old_code, new_code)
WHERE ua.subdistrict_code = m.old_code;

