FROM public.address_th_district AS d
WHERE s.district_id = d.id::bigint AND d.id IN ('3801', '4906', '9310', '9508');

-- Step 6: delete 4 codes DOPA does not list (abort if any saved address uses them)
DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM public.user_address WHERE subdistrict_code IN ('200409', '920221', '920222', '920414');
  IF n > 0 THEN RAISE EXCEPTION 'user_address still references deleted codes: %', n; END IF;
END $$;
DELETE FROM public.address_th_subdistrict WHERE id IN ('200409', '920221', '920222', '920414');

-- Step 7: subdistrict codes must now equal DOPA's active list exactly
DO $$
DECLARE n int; h text;
BEGIN
  SELECT count(*), md5(string_agg(id, ',' ORDER BY id)) INTO n, h FROM public.address_th_subdistrict;
  IF n <> 7436 OR h <> '18892d7089a8755886b5b94a1a655cb9' THEN
    RAISE EXCEPTION 'subdistrict codes differ from DOPA: count % (expected 7436), md5 %', n, h;
  END IF;
END $$;
